import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # --- Build initial state from target_state ---
    current_state = {}
    orig_last_seq = {}

    for row in target_state.itertuples(index=False):
        order_id = row.order_id
        current_state[order_id] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }
        orig_last_seq[order_id] = row.last_seq

    # --- Dedup events by seq (at-least-once delivery) ---
    events = cdc_events.drop_duplicates(subset=["seq"], keep="first").copy()
    # Sort by seq (the only trusted ordering)
    events = events.sort_values("seq", kind="mergesort")

    last_event_op = {}
    last_event_seq = {}

    for row in events.itertuples(index=False):
        order_id = row.order_id
        seq = row.seq
        op = row.op
        status = row.status
        amount = row.amount

        # Replay guard: based on ORIGINAL target_state's last_seq only
        if order_id in orig_last_seq and seq <= orig_last_seq[order_id]:
            continue

        if op in ("I", "U"):
            if order_id in current_state:
                new_status = status
                if op == "U" and pd.isna(amount):
                    new_amount = current_state[order_id]["amount"]
                else:
                    new_amount = amount
                current_state[order_id] = {
                    "status": new_status,
                    "amount": new_amount,
                    "last_seq": seq,
                }
            else:
                current_state[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
            last_event_op[order_id] = op
            last_event_seq[order_id] = seq
        elif op == "D":
            if order_id in current_state:
                del current_state[order_id]
                last_event_op[order_id] = "D"
                last_event_seq[order_id] = seq
            # D for missing order does nothing, not recorded as an applied event

    # --- Build new_state output ---
    if current_state:
        new_state_rows = [
            {
                "order_id": order_id,
                "status": vals["status"],
                "amount": vals["amount"],
                "last_seq": vals["last_seq"],
            }
            for order_id, vals in current_state.items()
        ]
        new_state = pd.DataFrame(
            new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
        )
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Match dtypes where possible
    if not target_state.empty:
        for col in ["order_id", "last_seq"]:
            if col in new_state.columns:
                try:
                    new_state[col] = new_state[col].astype(target_state[col].dtype)
                except Exception:
                    pass

    # --- Build tombstones output ---
    tomb_rows = []
    for order_id, op in last_event_op.items():
        if op == "D":
            tomb_rows.append(
                {"order_id": order_id, "deleted_seq": last_event_seq[order_id]}
            )

    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    return {"new_state": new_state, "tombstones": tombstones}
